export interface BitApi {
  /**
   * Returns the bitwise arithmetic right-shift of its first argument by the number of bits given by the second argument.
   * Arithmetic right-shift treats the most-significant bit as a sign bit and replicates it.
   * Only the lower 5 bits of the shift count are used (reduces to the range [0..31]).
   *
   * **Examples:**
   *
   * ```lua
   * print(bit.arshift(256, 8))           --> 1
   * print(bit.arshift(-256, 8))          --> -1
   * printx(bit.arshift(0x87654321, 12))  --> 0xfff87654
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.arshift:x-n)
   *
   * @param x number
   *
   * @param n number of bits
   *
   * @returns y bitwise arithmetic right-shifted number
   */
  readonly arshift: {
    (x: number, n: number): number;
  };
  /**
   * Returns the bitwise and of all of its arguments. Note that more than two arguments are allowed.
   *
   * **Examples:**
   *
   * ```lua
   * printx(bit.band(0x12345678, 0xff))        --> 0x00000078
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.band:x1-x2...)
   *
   * @param x1 number
   *
   * @param arg2 number(s)
   *
   * @returns y bitwise and of the provided arguments
   */
  readonly band: {
    (x1: number, ...args: number[]): number;
  };
  /**
   * Returns the bitwise not of its argument.
   *
   * **Examples:**
   *
   * ```lua
   * print(bit.bnot(0))            --> -1
   * printx(bit.bnot(0))           --> 0xffffffff
   * print(bit.bnot(-1))           --> 0
   * print(bit.bnot(0xffffffff))   --> 0
   * printx(bit.bnot(0x12345678))  --> 0xedcba987
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.bnot:x)
   *
   * @param x number
   *
   * @returns y bitwise not of number x
   */
  readonly bnot: {
    (x: number): number;
  };
  /**
   * Returns the bitwise or of all of its arguments. Note that more than two arguments are allowed.
   *
   * **Examples:**
   *
   * ```lua
   * print(bit.bor(1, 2, 4, 8))                --> 15
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.bor:x1-x2...)
   *
   * @param x1 number
   *
   * @param arg2 number(s)
   *
   * @returns y bitwise or of the provided arguments
   */
  readonly bor: {
    (x1: number, ...args: number[]): number;
  };
  /**
   * Swaps the bytes of its argument and returns it. This can be used to convert little-endian 32 bit numbers to big-endian 32 bit numbers or vice versa.
   *
   * **Examples:**
   *
   * ```lua
   * printx(bit.bswap(0x12345678)) --> 0x78563412
   * printx(bit.bswap(0x78563412)) --> 0x12345678
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.bswap:x)
   *
   * @param x number
   *
   * @returns y bitwise swapped number
   */
  readonly bswap: {
    (x: number): number;
  };
  /**
   * Returns the bitwise xor of all of its arguments. Note that more than two arguments are allowed.
   *
   * **Examples:**
   *
   * ```lua
   * printx(bit.bxor(0xa5a5f0f0, 0xaa55ff00))  --> 0x0ff00ff0
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.bxor:x1-x2...)
   *
   * @param x1 number
   *
   * @param arg2 number(s)
   *
   * @returns y bitwise xor of the provided arguments
   */
  readonly bxor: {
    (x1: number, ...args: number[]): number;
  };
  /**
   * Returns the bitwise logical left-shift of its first argument by the number of bits given by the second argument.
   * Logical shifts treat the first argument as an unsigned number and shift in 0-bits.
   * Only the lower 5 bits of the shift count are used (reduces to the range [0..31]).
   *
   * **Examples:**
   *
   * ```lua
   * print(bit.lshift(1, 0))              --> 1
   * print(bit.lshift(1, 8))              --> 256
   * print(bit.lshift(1, 40))             --> 256
   * printx(bit.lshift(0x87654321, 12))   --> 0x54321000
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.lshift:x-n)
   *
   * @param x number
   *
   * @param n number of bits
   *
   * @returns y bitwise logical left-shifted number
   */
  readonly lshift: {
    (x: number, n: number): number;
  };
  /**
   * Returns the bitwise left rotation of its first argument by the number of bits given by the second argument. Bits shifted out on one side are shifted back in on the other side.
   * Only the lower 5 bits of the rotate count are used (reduces to the range [0..31]).
   *
   * **Examples:**
   *
   * ```lua
   * printx(bit.rol(0x12345678, 12))   --> 0x45678123
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.rol:x-n)
   *
   * @param x number
   *
   * @param n number of bits
   *
   * @returns y bitwise left-rotated number
   */
  readonly rol: {
    (x: number, n: number): number;
  };
  /**
   * Returns the bitwise right rotation of its first argument by the number of bits given by the second argument. Bits shifted out on one side are shifted back in on the other side.
   * Only the lower 5 bits of the rotate count are used (reduces to the range [0..31]).
   *
   * **Examples:**
   *
   * ```lua
   * printx(bit.ror(0x12345678, 12))   --> 0x67812345
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.ror:x-n)
   *
   * @param x number
   *
   * @param n number of bits
   *
   * @returns y bitwise right-rotated number
   */
  readonly ror: {
    (x: number, n: number): number;
  };
  /**
   * Returns the bitwise logical right-shift of its first argument by the number of bits given by the second argument.
   * Logical shifts treat the first argument as an unsigned number and shift in 0-bits.
   * Only the lower 5 bits of the shift count are used (reduces to the range [0..31]).
   *
   * **Examples:**
   *
   * ```lua
   * print(bit.rshift(256, 8))            --> 1
   * print(bit.rshift(-256, 8))           --> 16777215
   * printx(bit.rshift(0x87654321, 12))   --> 0x00087654
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.rshift:x-n)
   *
   * @param x number
   *
   * @param n number of bits
   *
   * @returns y bitwise logical right-shifted number
   */
  readonly rshift: {
    (x: number, n: number): number;
  };
  /**
   * Normalizes a number to the numeric range for bit operations and returns it. This function is usually not needed since all bit operations already normalize all of their input arguments.
   *
   * **Examples:**
   *
   * ```lua
   * print(0xffffffff)                --> 4294967295 (*)
   * print(bit.tobit(0xffffffff))     --> -1
   * printx(bit.tobit(0xffffffff))    --> 0xffffffff
   * print(bit.tobit(0xffffffff + 1)) --> 0
   * print(bit.tobit(2^40 + 1234))    --> 1234
   * ```
   *
   * (*) See the treatment of hex literals for an explanation why the printed numbers in the first two lines differ (if your Lua installation uses a double number type).
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.tobit:x)
   *
   * @param x number to normalize
   *
   * @returns y normalized number
   */
  readonly tobit: {
    (x: number): number;
  };
  /**
   * Converts its first argument to a hex string. The number of hex digits is given by the absolute value of the optional second argument. Positive numbers between 1 and 8 generate lowercase hex digits. Negative numbers generate uppercase hex digits. Only the least-significant 4*|n| bits are used. The default is to generate 8 lowercase hex digits.
   *
   * **Examples:**
   *
   * ```lua
   * print(bit.tohex(1))              --> 00000001
   * print(bit.tohex(-1))             --> ffffffff
   * print(bit.tohex(0xffffffff))     --> ffffffff
   * print(bit.tohex(-1, -8))         --> FFFFFFFF
   * print(bit.tohex(0x21, 4))        --> 0021
   * print(bit.tohex(0x87654321, 4))  --> 4321
   * ```
   *
   * [Open in Browser](https://defold.com/ref/bit-lua#bit.tohex:x-n)
   *
   * @param x number to convert
   *
   * @param n number of hex digits to return
   *
   * @returns s hexadecimal string
   */
  readonly tohex: {
    (x: number, n?: number): string;
  };
}

export interface BufferApi {
  /**
   * Functions for manipulating buffers and streams
   * float32 Float, single precision, 4 bytes
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.VALUE_TYPE)
   */
  readonly VALUE_TYPE_FLOAT32: BufferVALUETYPE;
  /**
   * int16 Signed integer, 2 bytes
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.VALUE_TYPE)
   */
  readonly VALUE_TYPE_INT16: BufferVALUETYPE;
  /**
   * int32 Signed integer, 4 bytes
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.VALUE_TYPE)
   */
  readonly VALUE_TYPE_INT32: BufferVALUETYPE;
  /**
   * int64 Signed integer, 8 bytes
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.VALUE_TYPE)
   */
  readonly VALUE_TYPE_INT64: BufferVALUETYPE;
  /**
   * int8 Signed integer, 1 byte
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.VALUE_TYPE)
   */
  readonly VALUE_TYPE_INT8: BufferVALUETYPE;
  /**
   * uint16 Unsigned integer, 2 bytes
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.VALUE_TYPE)
   */
  readonly VALUE_TYPE_UINT16: BufferVALUETYPE;
  /**
   * uint32 Unsigned integer, 4 bytes
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.VALUE_TYPE)
   */
  readonly VALUE_TYPE_UINT32: BufferVALUETYPE;
  /**
   * uint64 Unsigned integer, 8 bytes
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.VALUE_TYPE)
   */
  readonly VALUE_TYPE_UINT64: BufferVALUETYPE;
  /**
   * uint8 Unsigned integer, 1 byte
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.VALUE_TYPE)
   */
  readonly VALUE_TYPE_UINT8: BufferVALUETYPE;
  /**
   * | `buffer.VALUE_TYPE_FLOAT32`
   * | `buffer.VALUE_TYPE_INT16`
   * | `buffer.VALUE_TYPE_INT32`
   * | `buffer.VALUE_TYPE_INT64`
   * | `buffer.VALUE_TYPE_INT8`
   * | `buffer.VALUE_TYPE_UINT16`
   * | `buffer.VALUE_TYPE_UINT32`
   * | `buffer.VALUE_TYPE_UINT64`
   * | `buffer.VALUE_TYPE_UINT8`
   * Copy all data streams from one buffer to another, element wise.
   *
   * Each of the source streams must have a matching stream in the
   * destination buffer. The streams must match in both type and size.
   * The source and destination buffer can be the same.
   *
   * **Examples:**
   *
   * How to copy elements (e.g. vertices) from one buffer to another
   *
   * ```lua
   * -- copy entire buffer
   * buffer.copy_buffer(dstbuffer, 0, srcbuffer, 0, #srcbuffer)
   *
   * -- copy last 10 elements to the front of another buffer
   * buffer.copy_buffer(dstbuffer, 0, srcbuffer, #srcbuffer - 10, 10)
   * ```
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.copy_buffer:dst-dstoffset-src-srcoffset-count)
   *
   * @param dst the destination buffer
   *
   * @param dstoffset the offset to start copying data to
   *
   * @param src the source data buffer
   *
   * @param srcoffset the offset to start copying data from
   *
   * @param count the number of elements to copy
   */
  readonly copyBuffer: {
    (dst: BufferData, dstoffset: number, src: BufferData, srcoffset: number, count: number): void;
  };
  /**
   * Copy a specified amount of data from one stream to another.
   *
   * The value type and size must match between source and destination streams.
   * The source and destination streams can be the same.
   *
   * **Examples:**
   *
   * How to update a texture of a sprite:
   *
   * ```lua
   * -- copy entire stream
   * local srcstream = buffer.get_stream(srcbuffer, hash("xyz"))
   * local dststream = buffer.get_stream(dstbuffer, hash("xyz"))
   * buffer.copy_stream(dststream, 0, srcstream, 0, #srcstream)
   * ```
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.copy_stream:dst-dstoffset-src-srcoffset-count)
   *
   * @param dst the destination stream
   *
   * @param dstoffset the offset to start copying data to (measured in value type)
   *
   * @param src the source data stream
   *
   * @param srcoffset the offset to start copying data from (measured in value type)
   *
   * @param count the number of values to copy (measured in value type)
   */
  readonly copyStream: {
    (dst: BufferStream, dstoffset: number, src: BufferStream, srcoffset: number, count: number): void;
  };
  /**
   * Create a new data buffer containing a specified set of streams. A data buffer
   * can contain one or more streams with typed data. This is useful for managing
   * compound data, for instance a vertex buffer could contain separate streams for
   * vertex position, color, normal etc.
   *
   * **Examples:**
   *
   * How to create and initialize a buffer
   *
   * ```lua
   * function init(self)
   *   local size = 128
   *   self.image = buffer.create( size * size, { {name=hash("rgb"), type=buffer.VALUE_TYPE_UINT8, count=3 } })
   *   self.imagestream = buffer.get_stream(self.image, hash("rgb"))
   *
   *   for y=0,self.height-1 do
   *      for x=0,self.width-1 do
   *          local index = y * self.width * 3 + x * 3 + 1
   *          self.imagestream[index + 0] = self.r
   *          self.imagestream[index + 1] = self.g
   *          self.imagestream[index + 2] = self.b
   *      end
   *   end
   * ```
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.create:element_count-declaration)
   *
   * @param elementCount The number of elements the buffer should hold
   *
   * @param declaration A table where each entry (table) describes a stream  - `hash|string` `name`: The name of the stream - `buffer.VALUE_TYPE` `type`: The data type of the stream - `number` `count`: The number of values each element should hold
   *
   * @returns buffer the new buffer
   */
  readonly create: {
    (elementCount: number, declaration: ReadonlyArray<Readonly<{ name: DefoldHash | string; type: BufferVALUETYPE; count: number }>>): BufferData;
  };
  /**
   * Get a copy of all the bytes from a specified stream as a Lua string.
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.get_bytes:buffer-stream_name)
   *
   * @param buffer the source buffer
   *
   * @param streamName the name of the stream
   *
   * @returns data the buffer data as a Lua string
   */
  readonly getBytes: {
    (buffer: BufferData, streamName: DefoldHash): string;
  };
  /**
   * Get a named metadata entry from a buffer along with its type.
   *
   * **Examples:**
   *
   * How to get a metadata entry from a buffer
   *
   * ```lua
   * -- retrieve a metadata entry named "somefloats" and its nomeric type
   * local values, type = buffer.get_metadata(buf, hash("somefloats"))
   * if metadata then print(#metadata.." values in 'somefloats'") end
   * ```
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.get_metadata:buf-metadata_name)
   *
   * @param buf the buffer to get the metadata from
   *
   * @param metadataName name of the metadata entry
   *
   * @returns values table of metadata values or `nil` if the entry does not exist; value_type numeric type of values or `nil`
   */
  readonly getMetadata: {
    (buf: BufferData, metadataName: DefoldHash | string): readonly [ReadonlyArray<number> | null, BufferVALUETYPE | null];
  };
  /**
   * Get a specified stream from a buffer.
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.get_stream:buffer-stream_name)
   *
   * @param buffer the buffer to get the stream from
   *
   * @param streamName the stream name
   *
   * @returns stream the data stream
   */
  readonly getStream: {
    (buffer: BufferData, streamName: DefoldHash | string): BufferStream;
  };
  /**
   * Creates or updates a metadata array entry on a buffer.
   *
   * The value type and count given when updating the entry should match those used when first creating it.
   *
   * **Examples:**
   *
   * How to set a metadata entry on a buffer
   *
   * ```lua
   * -- create a new metadata entry with three floats
   * buffer.set_metadata(buf, hash("somefloats"), {1.5, 3.2, 7.9}, buffer.VALUE_TYPE_FLOAT32)
   * -- ...
   * -- update to a new set of values
   * buffer.set_metadata(buf, hash("somefloats"), {-2.5, 10.0, 32.2}, buffer.VALUE_TYPE_FLOAT32)
   * ```
   *
   * [Open in Browser](https://defold.com/ref/buffer-lua#buffer.set_metadata:buf-metadata_name-values-value_type)
   *
   * @param buf the buffer to set the metadata on
   *
   * @param metadataName name of the metadata entry
   *
   * @param values actual metadata, an array of numeric values
   *
   * @param valueType type of values when stored
   */
  readonly setMetadata: {
    (buf: BufferData, metadataName: DefoldHash | string, values: ReadonlyArray<number>, valueType: BufferVALUETYPE): void;
  };
}

