export interface Html5Api {
  /**
   * Executes the supplied string as JavaScript inside the browser.
   * A call to this function is blocking, the result is returned as-is, as a string.
   * (Internally this will execute the string using the `eval()` JavaScript function.)
   *
   * **Examples:**
   *
   * ```lua
   * local res = html5.run("10 + 20") -- returns the string "30"
   * print(res)
   * local res_num = tonumber(res) -- convert to number
   * print(res_num - 20) -- prints 10
   * ```
   *
   * [Open in Browser](https://defold.com/ref/html5-lua#html5.run:code)
   *
   * @param code Javascript code to run
   *
   * @returns result result as string
   */
  readonly run: {
    (code: string): string;
  };
  /**
   * Set a JavaScript interaction listener callaback from lua that will be
   * invoked when a user interacts with the web page by clicking, touching or typing.
   * The callback can then call DOM restricted actions like requesting a pointer lock,
   * or start playing sounds the first time the callback is invoked.
   *
   * **Examples:**
   *
   * ```lua
   * local function on_interaction(self)
   *     print("on_interaction called")
   *     html5.set_interaction_listener(nil)
   * end
   *
   * function init(self)
   *     html5.set_interaction_listener(on_interaction)
   * end
   * ```
   *
   * [Open in Browser](https://defold.com/ref/html5-lua#html5.set_interaction_listener:callback)
   *
   * @param callback The interaction callback. Pass an empty function or `nil` if you no longer wish to receive callbacks.  `self` `script_instance` The calling script instance
   */
  readonly setInteractionListener: {
    (callback?: ((self: ScriptInstance) => void) | null): void;
  };
}

export interface HttpApi {
  /**
   * Perform a HTTP/HTTPS request.
   *
   * If no timeout value is passed, the configuration value "network.http_timeout" is used. If that is not set, the timeout value is `0` (which blocks indefinitely).
   *
   * **Examples:**
   *
   * Basic HTTP-GET request. The callback receives a table with the response
   * in the fields status, the response (the data) and headers (a table).
   *
   * ```lua
   * local function http_result(self, _, response)
   *     if response.bytes_total ~= nil then
   *         update_my_progress_bar(self, response.bytes_received / response.bytes_total)
   *     else
   *         print(response.status)
   *         print(response.response)
   *         pprint(response.headers)
   *     end
   * end
   *
   * function init(self)
   *     http.request("http://www.google.com", "GET", http_result, nil, nil, { report_progress = true })
   * end
   * ```
   *
   * [Open in Browser](https://defold.com/ref/http-lua#http.request:url-method-callback-headers-post_data-options)
   *
   * @param url target url
   *
   * @param method HTTP/HTTPS method, e.g. "GET", "PUT", "POST" etc.
   *
   * @param callback response callback function  `self` `script_instance` The current script instance  `id` `hash` Internal message identifier. Do not use!
   *
   * @param headers optional table with custom headers
   *
   * @param postData optional data to send
   *
   * @param options optional request options
   */
  readonly request: {
    (url: string, method: string, callback: (self: ScriptInstance, id: DefoldHash, response: HttpResponse) => void, headers?: Readonly<Record<string, string>>, postData?: string, options?: HttpRequestOptions): void;
  };
}

export interface ImageApi {
  /**
   * Functions for creating image objects.
   * Luminance image type.
   *
   * [Open in Browser](https://defold.com/ref/image-lua#image.TYPE)
   */
  readonly TYPE_LUMINANCE: ImageTYPE;
  /**
   * Luminance-alpha image type.
   *
   * [Open in Browser](https://defold.com/ref/image-lua#image.TYPE)
   */
  readonly TYPE_LUMINANCE_ALPHA: ImageTYPE;
  /**
   * RGB image type.
   *
   * [Open in Browser](https://defold.com/ref/image-lua#image.TYPE)
   */
  readonly TYPE_RGB: ImageTYPE;
  /**
   * RGBA image type.
   *
   * [Open in Browser](https://defold.com/ref/image-lua#image.TYPE)
   */
  readonly TYPE_RGBA: ImageTYPE;
  /**
   * | `image.TYPE_RGB`
   * | `image.TYPE_RGBA`
   * | `image.TYPE_LUMINANCE`
   * | `image.TYPE_LUMINANCE_ALPHA`
   * get the header of an .astc buffer
   *
   * **Examples:**
   *
   * How to get the block size and dimensions from a .astc file
   *
   * ```lua
   * local s = sys.load_resource("/assets/cat.astc")
   * local header = image.get_astc_header(s)
   * pprint(s)
   * ```
   *
   * [Open in Browser](https://defold.com/ref/image-lua#image.get_astc_header:buffer)
   *
   * @param buffer .astc file data buffer
   *
   * @returns header header, or `nil` if the buffer is not a valid ASTC image
   */
  readonly getAstcHeader: {
    (buffer: string): ImageAstcHeader | null;
  };
  /**
   * Load image (PNG or JPEG) from buffer.
   *
   * **Examples:**
   *
   * How to load an image from an URL and create a GUI texture from it:
   *
   * ```lua
   * local imgurl = "http://www.site.com/image.png"
   * http.request(imgurl, "GET", function(self, id, response)
   *         local img = image.load(response.response)
   *         local tx = gui.new_texture("image_node", img.width, img.height, img.type, img.buffer)
   *     end)
   * ```
   *
   * [Open in Browser](https://defold.com/ref/image-lua#image.load:buffer-options)
   *
   * @param buffer image data buffer
   *
   * @param options Optional loading parameters. A boolean is accepted for backwards compatibility and controls `premultiply_alpha`.
   *
   * @returns image loaded image, or `nil` if loading fails
   */
  readonly load: {
    (buffer: string, options?: boolean | ImageLoadOptions): ImageLoadResult | null;
  };
  /**
   * Load image (PNG or JPEG) from a string buffer.
   *
   * **Examples:**
   *
   * Load an image from an URL as a buffer and create a texture resource from it:
   *
   * ```lua
   * local imgurl = "http://www.site.com/image.png"
   * http.request(imgurl, "GET", function(self, id, response)
   *         local img = image.load_buffer(response.response, { flip_vertically = true })
   *         local tparams = {
   *             width  = img.width,
   *             height = img.height,
   *             type   = graphics.TEXTURE_TYPE_2D,
   *             format = graphics.TEXTURE_FORMAT_RGBA }
   *
   *         local my_texture_id = resource.create_texture("/my_custom_texture.texturec", tparams, img.buffer)
   *         -- Apply the texture to a model
   *         go.set("/go1#model", "texture0", my_texture_id)
   *     end)
   * ```
   *
   * [Open in Browser](https://defold.com/ref/image-lua#image.load_buffer:buffer-options)
   *
   * @param buffer image data buffer
   *
   * @param options Optional loading parameters. A boolean is accepted for backwards compatibility and controls `premultiply_alpha`.
   *
   * @returns image loaded image, or `nil` if loading fails
   */
  readonly loadBuffer: {
    (buffer: string, options?: boolean | ImageLoadOptions): ImageLoadBufferResult | null;
  };
}

export interface JsonApi {
  /**
   * Manipulation of JSON data strings.
   * Represents the null primitive from a json file
   *
   * [Open in Browser](https://defold.com/ref/json-lua#json.null)
   */
  readonly null: unknown;
  /**
   * Decode a string of JSON data into a Lua table.
   * A Lua error is raised for syntax errors.
   *
   * **Examples:**
   *
   * Converting a string containing JSON data into a Lua table:
   *
   * ```lua
   * function init(self)
   *     local jsonstring = '{"persons":[{"name":"John Doe"},{"name":"Darth Vader"}]}'
   *     local data = json.decode(jsonstring)
   *     pprint(data)
   * end
   * ```
   *
   * Results in the following printout:
   *
   * ```
   * {
   *   persons = {
   *     1 = {
   *       name = John Doe,
   *     }
   *     2 = {
   *       name = Darth Vader,
   *     }
   *   }
   * }
   * ```
   *
   * [Open in Browser](https://defold.com/ref/json-lua#json.decode:json-options)
   *
   * @param json json data
   *
   * @param options optional decoding options
   *
   * @returns data decoded JSON value
   */
  readonly decode: {
    (json: string, options?: JsonDecodeOptions): unknown;
  };
  /**
   * Encode a lua table to a JSON string.
   * A Lua error is raised for syntax errors.
   *
   * **Examples:**
   *
   * Convert a lua table to a JSON string:
   *
   * ```lua
   * function init(self)
   *      local tbl = {
   *           persons = {
   *                { name = "John Doe"},
   *                { name = "Darth Vader"}
   *           }
   *      }
   *      local jsonstring = json.encode(tbl)
   *      pprint(jsonstring)
   * end
   * ```
   *
   * Results in the following printout:
   *
   * ```
   * {"persons":[{"name":"John Doe"},{"name":"Darth Vader"}]}
   * ```
   *
   * [Open in Browser](https://defold.com/ref/json-lua#json.encode:tbl-options)
   *
   * @param tbl Lua value to encode
   *
   * @param options optional encoding options
   *
   * @returns json encoded json
   */
  readonly encode: {
    (tbl: unknown, options?: JsonEncodeOptions): string;
  };
}

export interface LabelApi {
  /**
   * Returns the sprites and links found in the label's current layout.
   * Each entry contains `type`, `id`, the zero-based UTF-32 `text_offset`,
   * `text_length`, resolved `x`, `y`, `width`
   * and `height`, and an `attributes` table. The position is the lower-left
   * object corner relative to the label's upper-left layout origin.
   * Inline resource rendering is not part of this MVP; sprites use their explicit
   * dimensions or a one-em square fallback.
   *
   * **Examples:**
   *
   * ```lua
   * local objects = label.get_layout_objects("#label")
   * for _, object in ipairs(objects) do
   *     if object.type == "link" then
   *         print(object.attributes.src, object.text_offset, object.text_length)
   *     elseif object.type == "sprite" then
   *         print(object.attributes.src, object.x, object.y, object.width, object.height)
   *     end
   * end
   * ```
   *
   * [Open in Browser](https://defold.com/ref/label-lua#label.get_layout_objects:url)
   *
   * @param url the label to inspect
   *
   * @returns objects layout objects in source order
   */
  readonly getLayoutObjects: {
    (url: DefoldAddress): ReadonlyArray<LabelLayoutObject>;
  };
  /**
   * Gets the text from a label component
   *
   * This function is deprecated. Use `go.get("#label", "text")` instead.
   *
   * **Examples:**
   *
   * ```lua
   * function init(self)
   *     local text = go.get("#label", "text")
   *     print(text)
   * end
   * ```
   *
   * [Open in Browser](https://defold.com/ref/label-lua#label.get_text:url)
   *
   * @param url the label to get the text from
   *
   * @returns text the label text
   */
  readonly getText: {
    (url: DefoldAddress): string;
  };
  /**
   * Sets the text of a label component
   *
   * This function is deprecated. Use `go.set("#label", "text", value)` instead.
   *
   * This method uses the message passing that means the value will be set after `dispatch messages` step.
   * More information is available in the [Application Lifecycle manual](/manuals/application-lifecycle).
   *
   * **Examples:**
   *
   * ```lua
   * function init(self)
   *     go.set("#label", "text", "Hello World!")
   * end
   * ```
   *
   * [Open in Browser](https://defold.com/ref/label-lua#label.set_text:url-text)
   *
   * @param url the label that should have a constant set
   *
   * @param text the text
   */
  readonly setText: {
    (url: DefoldAddress, text: string | number): void;
  };
}

export interface LiveupdateApi {
  /**
   * Functions and constants to access resources.
   * Mismatch between between expected bundled resources and actual bundled resources. The manifest expects a resource to be in the bundle, but it was not found in the bundle. This is typically the case when a non-excluded resource was modified between publishing the bundle and publishing the manifest.
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_BUNDLED_RESOURCE_MISMATCH: LiveupdateLIVEUPDATE;
  /**
   * Mismatch between running engine version and engine versions supported by manifest.
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_ENGINE_VERSION_MISMATCH: LiveupdateLIVEUPDATE;
  /**
   * Failed to parse manifest data buffer. The manifest was probably produced by a different engine version.
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_FORMAT_ERROR: LiveupdateLIVEUPDATE;
  /**
   * Argument was invalid
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_INVAL: LiveupdateLIVEUPDATE;
  /**
   * The handled resource is invalid.
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_INVALID_HEADER: LiveupdateLIVEUPDATE;
  /**
   * The header of the resource is invalid.
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_INVALID_RESOURCE: LiveupdateLIVEUPDATE;
  /**
   * I/O operation failed
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_IO_ERROR: LiveupdateLIVEUPDATE;
  /**
   * Memory wasn't allocated
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_MEM_ERROR: LiveupdateLIVEUPDATE;
  /**
   * Operation completed successfully.
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_OK: LiveupdateLIVEUPDATE;
  /**
   * Mismatch between scheme used to load resources. Resources are loaded with a different scheme than from manifest, for example over HTTP or directly from file. This is typically the case when running the game directly from the editor instead of from a bundle.
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_SCHEME_MISMATCH: LiveupdateLIVEUPDATE;
  /**
   * Mismatch between expected and actual integrity data for legacy liveupdate verification.
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_SIGNATURE_MISMATCH: LiveupdateLIVEUPDATE;
  /**
   * Unspecified error
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_UNKNOWN: LiveupdateLIVEUPDATE;
  /**
   * Mismatch between manifest expected version and actual version.
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.LIVEUPDATE)
   */
  readonly LIVEUPDATE_VERSION_MISMATCH: LiveupdateLIVEUPDATE;
  /**
   * | `liveupdate.LIVEUPDATE_BUNDLED_RESOURCE_MISMATCH`
   * | `liveupdate.LIVEUPDATE_ENGINE_VERSION_MISMATCH`
   * | `liveupdate.LIVEUPDATE_FORMAT_ERROR`
   * | `liveupdate.LIVEUPDATE_INVAL`
   * | `liveupdate.LIVEUPDATE_INVALID_HEADER`
   * | `liveupdate.LIVEUPDATE_INVALID_RESOURCE`
   * | `liveupdate.LIVEUPDATE_IO_ERROR`
   * | `liveupdate.LIVEUPDATE_MEM_ERROR`
   * | `liveupdate.LIVEUPDATE_OK`
   * | `liveupdate.LIVEUPDATE_SCHEME_MISMATCH`
   * | `liveupdate.LIVEUPDATE_SIGNATURE_MISMATCH`
   * | `liveupdate.LIVEUPDATE_UNKNOWN`
   * | `liveupdate.LIVEUPDATE_VERSION_MISMATCH`
   * Adds a resource mount to the resource system.
   * After the mount succeeded, the resources are available to load. (i.e. no reboot required)
   *
   * **Examples:**
   *
   * Add multiple mounts. Higher priority takes precedence.
   *
   * ```lua
   * liveupdate.add_mount("common", "zip:/path/to/common_stuff.zip", 10, function (self, name, uri, result) end) -- base pack
   * liveupdate.add_mount("levelpack_1", "zip:/path/to/levels_1_to_20.zip", 20, function (self, name, uri, result) end) -- level pack
   * liveupdate.add_mount("season_pack_1", "zip:/path/to/easter_pack_1.zip", 30, function (self, name, uri, result) end) -- season pack, overriding content in the other packs
   * ```
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.add_mount:name-uri-priority-callback)
   *
   * @param name Unique name of the mount
   *
   * @param uri The uri of the mount, including the scheme. Currently supported schemes are 'zip' and 'archive'.
   *
   * @param priority Priority of mount. Larger priority takes prescedence
   *
   * @param callback Callback after the asynchronous request completed - `name` `hash` Unique name of the mount - `uri` `string` The uri of the mount - `result` `liveupdate.LIVEUPDATE` The result of the request
   *
   * @returns result The result of the request
   */
  readonly addMount: {
    (name: string | DefoldHash, uri: string, priority: number, callback: (self: ScriptInstance, name: DefoldHash, uri: string, result: LiveupdateLIVEUPDATE) => void): LiveupdateLIVEUPDATE;
  };
  /**
   * Get an array of the current mounts
   * This can be used to determine if a new mount is needed or not
   *
   * **Examples:**
   *
   * Output the current resource mounts
   *
   * ```lua
   * pprint("MOUNTS", liveupdate.get_mounts())
   * ```
   *
   * Give an output like:
   *
   * ```lua
   * DEBUG:SCRIPT: MOUNTS,
   * { --[[0x119667bf0]]
   *   1 = { --[[0x119667c50]]
   *     name = hash: [liveupdate],
   *     uri = "zip:/device/path/to/acchives/liveupdate.zip",
   *     priority = 5
   *   },
   *   2 = { --[[0x119667d50]]
   *     name = hash: [_base],
   *     uri = "archive:build/default/game.dmanifest",
   *     priority = -10
   *   }
   * }
   * ```
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.get_mounts:)
   *
   * @returns mounts Array of mounts
   */
  readonly getMounts: {
    (): ReadonlyArray<Readonly<{ name: DefoldHash; uri: string; priority: number }>>;
  };
  /**
   * Checks if the bundled application was built with one or more resources
   * excluded from the main bundle, through a collection proxy with
   * `Exclude` enabled.
   *
   * This value is based on metadata in the bundled manifest. It does not check
   * whether any live update archive has been mounted or whether the excluded
   * resources are currently available on device.
   *
   * **Examples:**
   *
   * ```lua
   * if liveupdate.is_built_with_excluded_files() then
   *     print("The bundle expects live update content.")
   * end
   * ```
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.is_built_with_excluded_files:)
   *
   * @returns is_built_with_excluded_files true if the bundled application was built with excluded files
   */
  readonly isBuiltWithExcludedFiles: {
    (): boolean;
  };
  /**
   * Remove a mount the resource system.
   * Removing a mount does not affect any loaded resources.
   *
   * **Examples:**
   *
   * Add multiple mounts. Higher priority takes precedence.
   *
   * ```lua
   * liveupdate.remove_mount("season_pack_1")
   * ```
   *
   * [Open in Browser](https://defold.com/ref/liveupdate-lua#liveupdate.remove_mount:name)
   *
   * @param name Unique name of the mount
   *
   * @returns result The result of the call
   */
  readonly removeMount: {
    (name: string | DefoldHash): LiveupdateLIVEUPDATE;
  };
}

